      currentDay: 5,
      programDayContent: {
        title: "Day 5: Build active range",
        focus: "Active flexion practice",
        summary: "Add a controlled active range block.",
        exerciseSlugs: ["gentle-finger-bends"],
        faqSlugs: ["finger-swelling-after-cast"],
      },
